(44, '530.5x Giang Biên_Long Biên_nhà anh Thành', 'IMG_0610-1-768x1024.jpg,IMG_0611-1-768x1024.jpg,IMG_0612-1-1024x768 (1).jpg', '<h3 class=\"listivo-listing-section__label\" style=\"outline: none; border: 0px; margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px; line-height: var(--e-global-typography-lheading3-line-height);\">Mô tả</h3><p style=\"outline: none; border: 0px; margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px; line-height: var(--e-global-typography-lheading3-line-height);\"><span style=\"outline: none; border: 0px;\">Nội thất:</span><br style=\"outline: none; border: 0px;\"><span style=\"outline: none; border: 0px;\">✅ Điều hoà, nóng lạnh</span><br style=\"outline: none; border: 0px;\"><span style=\"outline: none; border: 0px;\">✅ Tủ quần áo, giường</span><br style=\"outline: none; border: 0px;\"><span style=\"outline: none; border: 0px;\">✅ Tủ bếp trên dưới, hút mùi, bếp từ</span><br style=\"outline: none; border: 0px;\"><span style=\"outline: none; border: 0px;\">✅ Tủ lạnh</span><br style=\"outline: none; border: 0px;\"><span style=\"outline: none; border: 0px;\">✅ Bàn ghế</span></p><p style=\"outline: none; border: 0px; margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px; line-height: var(--e-global-typography-lheading3-line-height);\"><span style=\"outline: none; border: 0px;\"><span style=\"outline: none; border: 0px;\">Ngoại thất:</span><br style=\"outline: none; border: 0px;\"><span style=\"outline: none; border: 0px;\">✅ Thang máy</span><br style=\"outline: none; border: 0px;\"><span style=\"outline: none; border: 0px;\">✅ Khóa vân tay</span><br style=\"outline: none; border: 0px;\"><span style=\"outline: none; border: 0px;\">✅ Camera giám sát</span><br style=\"outline: none; border: 0px;\"><span style=\"outline: none; border: 0px;\">✅ Thiết bị PCCC tự động, báo cháy, thang thoát hiểm</span><br style=\"outline: none; border: 0px;\"><span style=\"outline: none; border: 0px;\