INSERT INTO `bai_viet` (`id`, `tieu_de`, `anh_gioi_thieu`, `noi_dung`, `tinh_thanhpho_id`, `quan_huyen_id`, `phuong_xa_id`, `gia_tien`, `dien_tich`, `user_id`, `type`, `created_at`, `updated_at`) VALUES
(45, '77.X Tứ Liên_Tây Hồ_Trục 1_nhà chị Phương Anh', 'IMG_8722-768x1024.jpg,IMG_8723-1024x768.jpg,IMG_8725-1024x604.jpg', '<h3 class=\"listivo-listing-section__label\" style=\"outline: none; border: 0px; margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px; line-height: var(--e-global-typography-lheading3-line-height);\">Mô tả</h3><div class=\"listivo-listing-section__text\" style=\"outline: none; border: 0px; line-height: var(--e-global-typography-ltext1-line-height);\"><p data-start=\"0\" data-end=\"82\" style=\"outline: none; border: 0px; margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px;\"><span style=\"outline-color: initial; outline-width: initial; border-style: initial; border-color: initial; border-image: initial;\">Giới thiệu chung cư mini mới tại Tứ Liên, Tây Hồ – Khu vực trung tâm siêu hot!</span></p><p data-start=\"84\" data-end=\"414\" style=\"outline: none; border: 0px; margin-top: var(--e-global-size-6); margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px;\">Chung cư mini mới tại&nbsp;<span style=\"outline-color: initial; outline-width: initial; border-style: initial; border-color: initial; border-image: initial;\">Tứ Liên, Tây Hồ</span>&nbsp;là sự lựa chọn lý tưởng cho những ai muốn tận hưởng không gian sống hiện đại, đầy đủ tiện nghi, tại vị trí trung tâm, dễ dàng di chuyển đến các khu vực trọng điểm của Hà Nội. Với không gian rộng rãi, tiện nghi và môi trường sống thoáng đãng, đây chắc chắn sẽ là nơi lý tưởng để bạn an cư.</p><h3 data-start=\"416\" data-end=\"452\" style=\"outline: none; border: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px;\"><span data-start=\"420\" data-end=\"452\" style=\"outline: none; border: 0px;\">Tiện ích đầy đủ và hiện đại:</span></h3><ul data-start=\"453\" data-end=\"895\" style=\"outline: none; border: 0px; margin: 1em 0px; padding: 0px; list-style-position: outside; list-style-image: none;\"><li data-start=\"453\" data-end=\"554\" style=\"outline: none; border: 0px; margin: 0px; list-style: inside;\"><span style=\"outline-color: initial; outline-width: initial; border-style: initial; border-color: initial; border-image: initial;\">Điều hòa, nóng lạnh</span>: Mang đến không gian sống dễ chịu, thoải mái trong mọi điều kiện thời tiết.</li><li data-start=\"555\" data-end=\"633\" style=\"outline: none; border: 0px; margin: 0px; list-style: inside;\"><span style=\"outline-color: initial; outline-width: initial; border-style: initial; border-color: initial; border-image: initial;\">Giường, đệm, tủ quần áo</span>: Tạo không gian ngủ nghỉ tiện nghi và thoải mái.</li><li data-start=\"634\" data-end=\"742\" style=\"outline: none; border: 0px; margin: 0px; list-style: inside;\"><span style=\"outline-color: initial; outline-width: initial; border-style: initial; border-color: initial; border-image: initial;\">Bàn ghế, tủ bếp</span>: Cung cấp các món đồ nội thất cơ bản giúp căn phòng thêm phần tiện nghi và sang trọng.</li><li data-start=\"743\" data-end=\"808\" style=\"outline: none; border: 0px; margin: 0px; list-style: inside;\"><span style=\"outline-color: initial; outline-width: initial; border-style: initial; border-color: initial; border-image: initial;\">Máy giặt chung</span>: Tiết kiệm chi phí và không gian cho cư dân.</li><li data-start=\"809\" data-end=\"895\" style=\"outline: none; border: 0px; margin: 0px; list-style: inside;\"><span style=\"outline-color: initial; outline-width: initial; border-style: initial; border-color: initial; border-image: initial;\">Khoá cửa vân tay</span>: An toàn và tiện lợi trong việc bảo vệ không gian sống của bạn.</li></ul><h3 data-start=\"897\" data-end=\"933\" style=\"outline: none; border: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px;\"><span style=\"outline-color: initial; outline-width: initial; border-style: initial; border-color: initial; border-image: initial;\">Chi phí dịch vụ và tiện ích:</span></h3><ul data-start=\"934\" data-end=\"1114\" style=\"outline: none; border: 0px; margin: 1em 0px; padding: 0px; list-style-position: outside; list-style-image: none;\"><li data-start=\"934\" data-end=\"959\" style=\"outline: none; border: 0px; margin: 0px; list-style: inside;\"><span style=\"outline-color: initial; outline-width: initial; border-style: initial; border-color: initial; border-image: initial;\">Điện</span>: 4.000 VNĐ/số.</li><li data-start=\"960\" data-end=\"996\" style=\"outline: none; border: 0px; margin: 0px; list-style: inside;\"><span style=\"outline-color: initial; outline-width: initial; border-style: initial; border-color: initial; border-image: initial;\">Nước</span>: 150.000 VNĐ/người/tháng.</li><li data-start=\"997\" data-end=\"1033\" style=\"outline: none; border: 0px; margin: 0px; list-style: inside;\"><span style=\"outline-color: initial; outline-width: initial; border-style: initial; border-color: initial; border-image: initial;\">Mạng</span>: 100.000 VNĐ/phòng/tháng.</li><li data-start=\"1034\" data-end=\"1114\" style=\"outline: none; border: 0px; margin: 0px; list-style: inside;\"><span style=\"outline-color: initial; outline-width: initial; border-style: initial; border-color: initial; border-image: initial;\">Dịch vụ chung (máy giặt, đèn hành lang, quản lý)</span>: 100.000 VNĐ/người/tháng.</li></ul><h3 data-start=\"1116\" data-end=\"1139\" style=\"outline: none; border: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px;\"><span style=\"outline-color: initial; outline-width: initial; border-style: initial; border-color: initial; border-image: initial;\">Cấu trúc phòng:</span></h3><ul data-start=\"1140\" data-end=\"1329\" style=\"outline: none; border: 0px; margin: 1em 0px; padding: 0px; list-style-position: outside; list-style-image: none;\"><li data-start=\"1140\" data-end=\"1230\" style=\"outline: none; border: 0px; margin: 0px; list-style: inside;\"><span style=\"outline-color: initial; outline-width: initial; border-style: initial; border-color: initial; border-image: initial;\">Phòng khép kín</span>, bếp ngoài ban công – tạo không gian thông thoáng và dễ dàng sử dụng.</li><li data-start=\"1231\" data-end=\"1329\" style=\"outline: none; border: 0px; margin: 0px; list-style: inside;\"><span style=\"outline-color: initial; outline-width: initial; border-style: initial; border-color: initial; border-image: initial;\">Máy giặt và phơi đồ</span>: Máy giặt được bố trí ở tầng 1 hoặc ban công, tiện lợi cho việc sử dụng.</li></ul><h3 data-start=\"1331\" data-end=\"1353\" style=\"outline: none; border: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px;\"><span style=\"outline-color: initial; outline-width: initial; border-style: initial; border-color: initial; border-image: initial;\">Tiện ích khác:</span></h3><ul data-start=\"1354\" data-end=\"1454\" style=\"outline: none; border: 0px; margin: 1em 0px; padding: 0px; list-style-position: outside; list-style-image: none;\"><li data-start=\"1354\" data-end=\"1454\" style=\"outline: none; border: 0px; margin: 0px; list-style: inside;\"><span style=\"outline-color: initial; outline-width: initial; border-style: initial; border-color: initial; border-image: initial;\">Ô tô đỗ trước ngõ</span>, chỉ cách cửa nhà khoảng 10m, dễ dàng di chuyển và tiện lợi cho việc đi lại.</li></ul><p data-start=\"1456\" data-end=\"1696\" data-is-last-node=\"\" data-is-only-node=\"\" style=\"outline: none; border: 0px; margin-top: var(--e-global-size-6); margin-right: 0px; margin-bottom: 0px; margin-left: 0px;\">Chung cư mini tại&nbsp;<span style=\"outline-color: initial; outline-width: initial; border-style: initial; border-color: initial; border-image: initial;\">Tứ Liên, Tây Hồ</span>&nbsp;là lựa chọn hoàn hảo cho những ai tìm kiếm một không gian sống đầy đủ tiện nghi, hiện đại, an ninh cao, và thuận tiện đi lại. Đừng bỏ lỡ cơ hội sở hữu một căn phòng đẹp tại khu vực trung tâm Hà Nội này!</p><h3 class=\"listivo-listing-simple-label\" style=\"outline: none; border: 0px; margin-right: 0px; margin-bot