INSERT INTO `bai_viet` (`id`, `tieu_de`, `anh_gioi_thieu`, `noi_dung`, `tinh_thanhpho_id`, `quan_huyen_id`, `phuong_xa_id`, `gia_tien`, `dien_tich`, `user_id`, `type`, `created_at`, `updated_at`) VALUES
(46, '1.9x Quan Hoa_Cầu Giấy_nhà anh Công', 'IMG_0605-scaled.jpeg,IMG_0594-768x1024.jpeg,IMG_0600-1024x768.jpeg', '<h3 class=\"listivo-listing-section__label\" style=\"outline: none; border: 0px; margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px; line-height: var(--e-global-typography-lheading3-line-height);\">Mô tả</h3><div class=\"listivo-listing-section__text\" style=\"outline: none; border: 0px; line-height: var(--e-global-typography-ltext1-line-height);\"><p style=\"color: var(--e-global-color-lcolor2); font-family: var(--e-global-typography-ltext1-font-family); background-color: rgb(253, 253, 254); outline: none; border: 0px; margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px;\">Nhà nằm tại vị trí đắc địa, gần trung tâm với vô vàn tiện ích, bước xuống nhà cái gì cũng có, đi 5-10 phút ra Ngã Tư Sở, nhà full đồ đầy đủ tiện nghi.</p><p style=\"color: var(--e-global-color-lcolor2); font-family: var(--e-global-typography-ltext1-font-family); background-color: rgb(253, 253, 254); outline: none; border: 0px; margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px;\"><br></p><p style=\"outline: none; border: 0px; margin-top: var(--e-global-size-6); margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px;\">🍡Diện tích: 30m*4 Tầng</p><p style=\"outline: none; border: 0px; margin-top: var(--e-global-size-6); margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px;\">🍡Dạng: Nguyên Căn&nbsp;</p><p style=\"outline: none; border: 0px; margin-top: var(--e-global-size-6); margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px;\">🍡Thang: thang bộ</p><p style=\"outline: none; border: 0px; margin-top: var(--e-global-size-6); margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px;\">Tầng 1: Nhà bếp</p><p style=\"outline: none; border: 0px; margin-top: var(--e-global-size-6); margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px;\">Tầng 2: Phòng khách + 1 ngủ 1vs</p><p style=\"outline: none; border: 0px; margin-top: var(--e-global-size-6); margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px;\">Tầng 3: 2 ngủ + 1 vệ sinh</p><p style=\"outline: none; border: 0px; margin-top: var(--e-global-size-6); margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px;\">Tầng 4: Phòng thờ và sân phơi&nbsp;</p><p style=\"outline: none; border: 0px; margin-top: var(--e-global-size-6); margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px;\">🐚 &nbsp;lNội thất : Điều hoà 03, nóng lạnh 03, giường 03, tủ quần áo 02, ti vi, sofa bàn trà, bàn ghế ăn, bếp từ, tủ lạnh 2 cánh, máy giặt, tủ bến trên dưới, hút mùi, kệ giày,…</p><p style=\"outline: none; border: 0px; margin-top: var(--e-global-size-6); margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px;\">DV: Điện nước giá dân dùng bao nhiêu trả bấy nhiêu</p><p style=\"outline: none; border: 0px; margin-top: var(--e-global-size-6); margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px;\"><br></p><p style=\"outline: none; border: 0px; margin-top: var(--e-global-size-6); margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px;\">📛Lưu ý:&nbsp;</p><p style=\"outline: none; border: 0px; margin-top: var(--e-global-size-6); margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px;\">– Hợp đồng :1 năm đến 3 năm</p><p style=\"outline: none; border: 0px; margin-top: var(--e-global-size-6); margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px;\">– Cọc 1 đóng 3 (đóng 6th được fix giá)&nbsp;</p><p style=\"outline: none; border: 0px; margin-top: var(--e-global-size-6); margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px;\">– Chỉ nhận ở gia đình&nbsp;</p><p style=\"outline: none; border: 0px; margin-top: var(--e-global-size-6); margin-right: 0px; margin-bottom: 0px; margin-left: 0px;\">– Không nhận CHDV, thuê cho thuê</p><h3 class=\"listivo-listing-simple-label\" style=\"outline: none; border: 0px; margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px; line-height: var(--e-global-typography-lheading3-line-height);\">Tiện nghi</h3><h3 class=\"listivo-listing-simple-label\" style=\"outline: none; border: 0px; margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px; line-height: var(--e-global-typography-lheading3-line-height);\"><div class=\"listivo-listing-feature\" style=\"outline: none; border: 0px; display: flex; color: rgb(0, 0, 0); font-family: Inter, sans-serif; font-size: 16px; background-color: rgb(253, 253, 254);\"><div class=\"listivo-listing-feature__icon-wrapper\" style=\"outline: none; border: 0px; display: flex; align-items: center; height: var(--e-global-typography-ltext1-line-height); margin-right: var(--e-global-size-7);\"><div class=\"listivo-listing-feature__icon\" style=\"outline: none; border: 0px; display: flex; align-items: center; justify-content: center; width: var(--e-global-size-5); height: var(--e-global-size-5); border-radius: 50%; background-color: var(--e-global-color-lprimary1);\"><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"12\" height=\"9\" viewBox=\"0 0 12 9\" fill=\"none\"><path d=\"M10.6633 0.000289842C10.4901 0.0054506 10.3257 0.0778367 10.205 0.202113L3.34299 7.06409L1.14768 4.86878C1.08625 4.8048 1.01267 4.75372 0.931251 4.71853C0.849832 4.68334 0.76221 4.66474 0.673516 4.66384C0.584823 4.66294 0.49684 4.67974 0.414722 4.71327C0.332604 4.7468 0.258001 4.79637 0.195282 4.85909C0.132563 4.92181 0.0829883 4.99641 0.0494622 5.07853C0.0159361 5.16065 -0.000867871 5.24863 3.45076e-05 5.33732C0.000936886 5.42602 0.0195273 5.51364 0.0547172 5.59506C0.0899072 5.67648 0.140989 5.75006 0.204971 5.81149L2.87164 8.47816C2.99667 8.60313 3.16621 8.67334 3.34299 8.67334C3.51977 8.67334 3.68932 8.60313 3.81435 8.47816L11.1477 1.14482C11.244 1.05118 11.3098 0.930619 11.3365 0.798939C1