(47, '530.5x Long Biên_phòng studio_nhà anh Thành', 'IMG_0310-1024x768.jpg,IMG_0308-1024x768.jpg,IMG_0309-1024x768.jpg', '<h3 class=\"listivo-listing-section__label\" style=\"outline: none; border: 0px; margin-right: 0px; margin-bottom: var(--e-global-size-4); margin-left: 0px; line-height: var(--e-global-typography-lheading3-line-height);\">Mô tả</h3><div class=\"listivo-listing-section__text\" style=\"outline: none; border: 0px; color: var(--e-global-color-lcolor2); font-family: var(--e-global-typography-ltext1-font-family); line-height: var(--e-global-typography-ltext1-line-height); background-color: rgb(253, 253, 254);\"><p style=\"outline: none; border: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: 0px;\"><span style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\">Nội thất:</span><br style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\"><span style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\">✅ Điều hoà, nóng lạnh</span><br style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\"><span style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\">✅ Tủ quần áo, giường</span><br style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\"><span style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\">✅ Tủ bếp trên dưới, hút mùi, bếp từ</span><br style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\"><span style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\">✅ Tủ lạnh</span><br style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\"><span style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\">✅ Bàn ghế</span><br style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\"><br style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\"><span style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\">Ngoại thất:</span><br style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\"><span style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\">✅ Thang máy</span><br style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\"><span style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\">✅ Khóa vân tay</span><br style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\"><span style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\">✅ Camera giám sát</span><br style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\"><span style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\">✅ Thiết bị PCCC tự động, báo cháy, thang thoát hiểm</span><br style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\"><span style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\">✅ Giặt sấy, phơi tầng 8</span><br style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\"><br style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\"><span style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\">– Điện: 4.000 / số</span><br style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\"><span style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\">– Nước: 30.000 / khối</span><br style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\"><span style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\">– Internet: 100.000 / phòng/ tháng</span><br style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\"><span style=\"outline: none; border: 0px; font-family: &quot;Times New Roman&quot;;\">– Dịch vụ chung: 150.000 / người/ tháng</span></p></div>', 1, 8, 75, 3500000, 25, 23, 0, '2025-03-17 07:42:16', '2025-03-17 07:42:16');

